lib/summary.sh.text:
#!/bin/bash
# Daily summary for subscribers: fills templates/daily-email.txt from one station archive file.
here=$(cd "$(dirname "$0")/.." && pwd)
d=${1:?date}
f="$here/archive/st01/$d.csv"
[ -f "$f" ] || { echo "no readings for $d" >&2; exit 1; }
max=$(cut -d, -f3 "$f" | sort -n | tail -1)
min=$(cut -d, -f3 "$f" | sort -n | head -1)
sed -e "s/{{date}}/$d/" -e "s/{{max}}/$max/" -e "s/{{min}}/$min/" "$here/templates/daily-email.txt"

tests/rotate_test.sh.text:
#!/bin/bash
# archive is laid out as archive/<station>/<date>.csv (docs/interfaces.md)
t=$(mktemp -d)
mkdir -p "$t/st01"
echo "st01,2026-01-01T00:00:00Z,1.0" > "$t/st01/2026-01-01.csv"
touch -d 2026-01-01 "$t/st01/2026-01-01.csv"
echo "st01,2026-11-01T00:00:00Z,1.0" > "$t/st01/2026-11-01.csv"
bash scripts/rotate.sh "$t" >/dev/null
[ -f "$t/st01/2026-01-01.csv.gz" ] || { echo "old file not compressed"; exit 1; }
[ ! -f "$t/st01/2026-01-01.csv" ] || { echo "old csv not removed"; exit 1; }
[ -f "$t/st01/2026-11-01.csv" ] || { echo "recent file touched"; exit 1; }

tests/summary_test.sh.text:
#!/bin/bash
fail=0
out=$(bash bin/stationlog summary 2026-11-01)
